CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,phone VARCHAR(32) NULL,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(160) NOT NULL,role VARCHAR(64) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS sessions (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,refresh_hash CHAR(64) NOT NULL UNIQUE,device_id VARCHAR(128) NULL,expires_at DATETIME(6) NOT NULL,revoked_at DATETIME(6) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX idx_sessions_user(user_id),CONSTRAINT fk_sessions_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs (id CHAR(36) PRIMARY KEY,actor_id CHAR(36) NULL,action VARCHAR(80) NOT NULL,resource VARCHAR(80) NOT NULL,resource_id CHAR(36) NULL,before_json JSON NULL,after_json JSON NULL,ip VARCHAR(64) NULL,user_agent VARCHAR(255) NULL,request_id VARCHAR(64) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX idx_audit_resource(resource,resource_id));
